/**
 * A statement mutation can block inside the Sail, for example while a store waits for another connection's writer
 * authority. Shutdown must reach that thread and close must not tear the connection down underneath it.
 */
@Timeout(60)
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class AbstractSailConnectionMutationShutdownTest {

	private static final String DEBUG_PROPERTY = "org.eclipse.rdf4j.repository.debug";
	private String previousDebug;

	@BeforeEach
	void disableDebug() {
		previousDebug = System.setProperty(DEBUG_PROPERTY, "false");
	}

	@AfterEach
	void restoreDebug() {
		if (previousDebug == null) {
			System.clearProperty(DEBUG_PROPERTY);
		} else {
			System.setProperty(DEBUG_PROPERTY, previousDebug);
		}
	}

	@Test
	void closeInterruptsAndDrainsAnInFlightStatementAddBeforeTeardown() throws Exception {
		assertMutationIsInterruptedAndDrained(
				connection -> connection.addStatement(RDF.FIRST, RDF.TYPE, RDF.PROPERTY));
	}

	@Test
	void closeInterruptsAndDrainsAnInFlightBulkStatementAddBeforeTeardown() throws Exception {
		assertMutationIsInterruptedAndDrained(connection -> connection.addStatements(
				List.of(SimpleValueFactory.getInstance().createStatement(RDF.REST, RDF.TYPE, RDF.PROPERTY))));
	}

	@Test
	void closeInterruptsAndDrainsAnInFlightStatementRemovalBeforeTeardown() throws Exception {
		assertMutationIsInterruptedAndDrained(connection -> connection.removeStatements(RDF.FIRST, null, null));
	}

	@Test
	void closeFromInsideAStatementMutationIsRejectedRatherThanDeadlocking() {
		AbstractSailConnection connection = newConnection();
		AtomicReference<Throwable> closeFailure = new AtomicReference<>();
		// A listener callback, for example, runs on the mutating thread; close would otherwise drain itself.
		doAnswer(invocation -> {
			try {
				connection.close();
			} catch (Throwable failure) {
				closeFailure.set(failure);
			}
			return null;
		}).when(connection)
				.addStatement(nullable(UpdateContext.class), any(Resource.class), any(IRI.class), any(Value.class),
						any(Resource[].class));
		connection.begin();

		connection.addStatement(RDF.FIRST, RDF.TYPE, RDF.PROPERTY);

		assertThat(closeFailure.get()).isInstanceOf(SailException.class)
				.hasMessage("An active connection operation cannot close its own connection");
		assertThat(connection.isOpen()).isTrue();
		connection.close();
		assertThat(connection.isOpen()).isFalse();
	}

	private static void assertMutationIsInterruptedAndDrained(Consumer<AbstractSailConnection> mutation)
			throws Exception {
		AbstractSailConnection connection = newConnection();
		AtomicBoolean teardownStarted = new AtomicBoolean();
		AtomicBoolean teardownStartedBeforeMutationReturned = new AtomicBoolean();
		CountDownLatch mutationEntered = new CountDownLatch(1);
		CountDownLatch mutationInterrupted = new CountDownLatch(1);
		CountDownLatch releaseMutation = new CountDownLatch(1);
		doAnswer(invocation -> {
			teardownStarted.set(true);
			return null;
		}).when(connection).closeInternal();
		// Mirrors a store whose write waits, interruptibly, for writer authority held by another connection.
		Answer<Void> blockingWrite = invocation -> {
			mutationEntered.countDown();
			boolean interrupted = false;
			while (releaseMutation.getCount() != 0) {
				try {
					releaseMutation.await();
				} catch (InterruptedException cancellation) {
					interrupted = true;
					mutationInterrupted.countDown();
				}
			}
			teardownStartedBeforeMutationReturned.set(teardownStarted.get());
			if (interrupted) {
				Thread.currentThread().interrupt();
			}
			return null;
		};
		doAnswer(blockingWrite).when(connection)
				.addStatement(nullable(UpdateContext.class), any(Resource.class), any(IRI.class), any(Value.class),
						any(Resource[].class));
		doAnswer(blockingWrite).when(connection)
				.removeStatement(nullable(UpdateContext.class), nullable(Resource.class), nullable(IRI.class),
						nullable(Value.class), any(Resource[].class));
		connection.begin();

		AtomicReference<Throwable> mutationFailure = new AtomicReference<>();
		AtomicReference<Throwable> closeFailure = new AtomicReference<>();
		Thread mutator = new Thread(() -> {
			try {
				mutation.accept(connection);
			} catch (Throwable failure) {
				mutationFailure.set(failure);
			}
		}, "in-flight-statement-mutation");
		Thread closer = new Thread(() -> {
			try {
				connection.close();
			} catch (Throwable failure) {
				closeFailure.set(failure);
			}
		}, "connection-close-during-mutation");
		mutator.start();
		try {
			assertTrue(mutationEntered.await(10, TimeUnit.SECONDS), "the mutation must enter the Sail write");
			closer.start();
			assertTrue(mutationInterrupted.await(10, TimeUnit.SECONDS),
					"close must interrupt the thread inside the statement mutation");
			assertThat(teardownStarted.get()).as("teardown must wait for the in-flight mutation").isFalse();
		} finally {
			releaseMutation.countDown();
			mutator.join(TimeUnit.SECONDS.toMillis(10));
			closer.join(TimeUnit.SECONDS.toMillis(10));
		}
		assertThat(mutator.isAlive()).isFalse();
		assertThat(closer.isAlive()).isFalse();
		assertThat(mutationFailure.get()).isNull();
		assertThat(closeFailure.get()).isNull();
		assertThat(teardownStartedBeforeMutationReturned.get()).as("the mutation returned before teardown")
				.isFalse();
		assertThat(teardownStarted.get()).isTrue();
	}

	private static AbstractSailConnection newConnection() {
		AbstractSail sail = mock(AbstractSail.class,
				withSettings().useConstructor().defaultAnswer(CALLS_REAL_METHODS));
		return mock(AbstractSailConnection.class, withSettings().useConstructor(sail)
				.defaultAnswer(CALLS_REAL_METHODS));
	}
}
